# Generated by `shiny theme new` from shiny-meteor.jpg
# Base scheme: Gruvbox Dark — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Gruvbox Dark"
GHOSTTY_THEME="Gruvbox Dark"   # built-in: ghostty +list-themes
ACCENT_PRESET=1                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#282828"         # window background
BG_DARK="#1D2021"    # frames, omnibox
SURFACE="#3C3836"    # borders, dividers, inactive window border
SELECTION="#504945"  # selected rows, text selection
MUTED="#665C54"      # shortcuts, scrollbar
COMMENT="#928374"    # subtext, inactive tabs
FG="#EBDBB2"         # primary text
FG_DIM="#D5C4A1"     # secondary text
ACCENT="#FE8019"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#8EC07C"    # secondary accent: cursor, shortcuts, search selection
